INSERT INTO exam_platform.attempt_responses VALUES ('5fa448a8-d155-4b4c-8d00-d05c4b2d7699', '46f57889-cb20-4490-a5a7-8233222d4bf4', 0, '00000000-0000-4000-a000-000000000202', '{"id": "00000000-0000-4000-a000-000000000202", "type": "mcq_single", "skill": "listening", "payload": {"prompt": "According to the lecturer, which factor most increases urban temperatures?", "options": [{"id": "A", "label": "Dense building materials"}, {"id": "B", "label": "Lack of vegetation"}, {"id": "C", "label": "Vehicle emissions"}, {"id": "D", "label": "Industrial activity"}], "passage": null, "audio_url": "/audio/listening/lecture_climate.m4a", "transcript": "Of the three drivers of urban heat we discussed, the absence of green space — not building materials or traffic — contributes the largest measurable temperature rise."}, "cefr_level": "B2", "estimated_seconds": 120}', 'mcq_single', '{"mcq_choice_id": "A"}', false, 0.000, 0.2478, 'listening', 50794, '2026-05-02 08:38:34.958477+00');
INSERT INTO exam_platform.attempt_responses VALUES ('785a96fd-549a-42ef-81d6-a0dc717a1b77', '46f57889-cb20-4490-a5a7-8233222d4bf4', 1, '00000000-0000-4000-a000-000000000602', '{"id": "00000000-0000-4000-a000-000000000602", "type": "matching_information", "skill": "reading", "payload": {"prompt": "Which paragraph mentions the year electric streetcars first ran?", "options": [{"id": "A", "label": "Paragraph A"}, {"id": "B", "label": "Paragraph B"}, {"id": "C", "label": "Paragraph C"}, {"id": "D", "label": "Paragraph D"}], "passage": "(A) The first electric streetcars began running in 1881. (B) By 1920 most major cities had electric tram networks. (C) Buses gradually replaced trams in the mid-20th century due to lower infrastructure costs. (D) Modern light rail systems revive many of the principles of early trams.", "audio_url": null}, "cefr_level": "B2", "estimated_seconds": 70}', 'matching_information', '{"mcq_choice_id": "A"}', true, 1.000, 0.0000, 'reading', 2026, '2026-05-02 08:38:38.819683+00');
INSERT INTO exam_platform.attempt_responses VALUES ('6d200bc0-ffae-4b12-b389-7d64cd918fbf', '46f57889-cb20-4490-a5a7-8233222d4bf4', 1, '00000000-0000-4000-a000-000000000601', '{"id": "00000000-0000-4000-a000-000000000601", "type": "true_false_ng", "skill": "reading", "payload": {"prompt": "Beekeeping has been practised for over five millennia.", "options": [{"id": "A", "label": "True"}, {"id": "B", "label": "False"}, {"id": "C", "label": "Not Given"}], "passage": "The honeybee, Apis mellifera, has been kept by humans for at least 8,000 years. Beekeepers harvest honey, beeswax, propolis and royal jelly. While honey is consumed worldwide, beeswax has industrial applications ranging from cosmetics to electronics. Recent declines in bee populations have raised concerns among ecologists, although the precise causes remain debated.", "audio_url": null}, "cefr_level": "B1", "estimated_seconds": 70}', 'true_false_ng', '{"mcq_choice_id": "B"}', false, 0.000, 0.4130, 'reading', 1906, '2026-05-02 08:38:41.468369+00');
INSERT INTO exam_platform.attempt_responses VALUES ('2d57c6c2-3d8d-4395-b993-250adeda0e4c', '46f57889-cb20-4490-a5a7-8233222d4bf4', 1, '00000000-0000-4000-a000-000000000603', '{"id": "00000000-0000-4000-a000-000000000603", "type": "sentence_completion", "skill": "reading", "payload": {"prompt": "The shrinking of the Aral Sea began in the ____.", "options": [{"id": "A", "label": "1940s"}, {"id": "B", "label": "1960s"}, {"id": "C", "label": "1980s"}, {"id": "D", "label": "2000s"}], "passage": "The Aral Sea, once the world''s fourth-largest lake, has shrunk to a fraction of its former size since the 1960s. Soviet-era irrigation projects diverted the Amu Darya and Syr Darya rivers to grow cotton, leaving the sea starved of inflow. Today the lakebed is a salt-encrusted desert known as the Aralkum.", "audio_url": null}, "cefr_level": "B1", "estimated_seconds": 70}', 'sentence_completion', '{"mcq_choice_id": "B"}', true, 1.000, -0.0010, 'reading', 2580, '2026-05-02 08:38:44.788218+00');
INSERT INTO exam_platform.attempt_responses VALUES ('068a3ab8-e604-4d82-9dfe-e7f568ab32dc', '46f57889-cb20-4490-a5a7-8233222d4bf4', 2, '00000000-0000-4000-a000-000000000501', '{"id": "00000000-0000-4000-a000-000000000501", "type": "writing_task1_academic", "skill": "writing", "payload": {"prompt": "The chart below shows the percentage of households in three Central Asian countries that owned a personal computer between 2000 and 2024.\n\nSummarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.", "options": null, "passage": null, "audio_url": null, "task_type": "task1_academic", "word_limit_max": 250, "word_limit_min": 150, "time_limit_minutes": 20}, "cefr_level": "B2", "estimated_seconds": 1200}', 'writing_task1_academic', '{"text_answer": "eerfd\nsdfsd\nsd\nfsd\nfsd\nfsdt\nyth\ntg\negbry\ntgsg\ntyhg\nerg"}', NULL, NULL, 0.0000, 'writing', 7651, '2026-05-02 08:38:54.469031+00');
INSERT INTO exam_platform.attempt_responses VALUES ('4cca8004-db5e-44c5-b097-ec70ea81b0e6', '46f57889-cb20-4490-a5a7-8233222d4bf4', 3, '00000000-0000-4000-a000-000000000402', '{"id": "00000000-0000-4000-a000-000000000402", "type": "speaking_part2_cue_card", "skill": "speaking", "payload": {"part": 2, "prompt": "Describe a memorable trip you took. You should say:\n  • where you went\n  • who you went with\n  • what you did there\nand explain why this trip was memorable for you.", "options": null, "passage": null, "audio_url": null, "speaking_seconds": 120, "preparation_seconds": 60}, "cefr_level": "B1", "estimated_seconds": 180}', 'speaking_part2_cue_card', '{"audio_bytes": 630828, "audio_base64": "", "audio_format": "wav"}', NULL, NULL, 0.0000, 'speaking', 6580, '2026-05-02 08:39:08.289313+00');
INSERT INTO exam_platform.attempt_responses VALUES ('d53b11db-f46e-401b-87b9-d9a14fb7f742', '303c40ca-e14d-418a-a8e5-7d0150e069cf', 0, '00000000-0000-4000-a000-000000000201', '{"id": "00000000-0000-4000-a000-000000000201", "type": "mcq_single", "skill": "listening", "payload": {"prompt": "How much does the library card cost per year?", "options": [{"id": "A", "label": "2,000 so''m"}, {"id": "B", "label": "5,000 so''m"}, {"id": "C", "label": "10,000 so''m"}, {"id": "D", "label": "Free"}], "passage": null, "audio_url": "/audio/listening/library_dialog.m4a", "transcript": "The annual library card is five thousand so''m and gives you access to every branch for twelve months."}, "cefr_level": "B1", "estimated_seconds": 120}', 'mcq_single', '{"mcq_choice_id": "B"}', true, 1.000, 0.0000, 'listening', 57004, '2026-05-02 08:46:03.742135+00');
INSERT INTO exam_platform.attempt_responses VALUES ('ac8abf79-5b36-45ae-a963-8886d360122a', '303c40ca-e14d-418a-a8e5-7d0150e069cf', 0, '00000000-0000-4000-a000-000000000202', '{"id": "00000000-0000-4000-a000-000000000202", "type": "mcq_single", "skill": "listening", "payload": {"prompt": "According to the lecturer, which factor most increases urban temperatures?", "options": [{"id": "A", "label": "Dense building materials"}, {"id": "B", "label": "Lack of vegetation"}, {"id": "C", "label": "Vehicle emissions"}, {"id": "D", "label": "Industrial activity"}], "passage": null, "audio_url": "/audio/listening/lecture_climate.m4a", "transcript": "Of the three drivers of urban heat we discussed, the absence of green space — not building materials or traffic — contributes the largest measurable temperature rise."}, "cefr_level": "B2", "estimated_seconds": 120}', 'mcq_single', '{"mcq_choice_id": "A"}', false, 0.000, 0.2478, 'listening', 47422, '2026-05-02 08:46:51.746207+00');
INSERT INTO exam_platform.attempt_responses VALUES ('95064092-444e-48f9-9708-57e922f02f09', '303c40ca-e14d-418a-a8e5-7d0150e069cf', 1, '00000000-0000-4000-a000-000000000602', '{"id": "00000000-0000-4000-a000-000000000602", "type": "matching_information", "skill": "reading", "payload": {"prompt": "Which paragraph mentions the year electric streetcars first ran?", "options": [{"id": "A", "label": "Paragraph A"}, {"id": "B", "label": "Paragraph B"}, {"id": "C", "label": "Paragraph C"}, {"id": "D", "label": "Paragraph D"}], "passage": "(A) The first electric streetcars began running in 1881. (B) By 1920 most major cities had electric tram networks. (C) Buses gradually replaced trams in the mid-20th century due to lower infrastructure costs. (D) Modern light rail systems revive many of the principles of early trams.", "audio_url": null}, "cefr_level": "B2", "estimated_seconds": 70}', 'matching_information', '{"mcq_choice_id": "A"}', true, 1.000, 0.0000, 'reading', 15094, '2026-05-02 08:47:09.366062+00');
