INSERT INTO exam_platform.attempt_responses VALUES ('37e7425f-a3a4-4ff2-9f57-e74b68b57f8d', '1a1ffc53-f9b7-48b0-b09c-d2b329c2e75c', 0, '00000000-0000-4000-a000-000000000201', '{"id": "00000000-0000-4000-a000-000000000201", "type": "mcq_single", "skill": "listening", "payload": {"prompt": "How much does the library card cost per year?", "options": [{"id": "A", "label": "2,000 so''m"}, {"id": "B", "label": "5,000 so''m"}, {"id": "C", "label": "10,000 so''m"}, {"id": "D", "label": "Free"}], "passage": null, "audio_url": "/audio/listening/library_dialog.m4a", "transcript": "The annual library card is five thousand so''m and gives you access to every branch for twelve months."}, "cefr_level": "B1", "estimated_seconds": 120}', 'mcq_single', '{"mcq_choice_id": "A"}', false, 0.000, 0.0000, 'listening', 92134, '2026-06-02 19:24:50.682881+00');
INSERT INTO exam_platform.attempt_responses VALUES ('ebe9034e-294c-459d-b91e-42505f9631f4', 'ee7d0677-ff5f-4975-a716-9142d4b76721', 0, '00000000-0000-4000-a000-000000000602', '{"id": "00000000-0000-4000-a000-000000000602", "type": "matching_information", "skill": "reading", "payload": {"prompt": "Which paragraph mentions the year electric streetcars first ran?", "options": [{"id": "A", "label": "Paragraph A"}, {"id": "B", "label": "Paragraph B"}, {"id": "C", "label": "Paragraph C"}, {"id": "D", "label": "Paragraph D"}], "passage": "(A) The first electric streetcars began running in 1881. (B) By 1920 most major cities had electric tram networks. (C) Buses gradually replaced trams in the mid-20th century due to lower infrastructure costs. (D) Modern light rail systems revive many of the principles of early trams.", "audio_url": null}, "cefr_level": "B2", "estimated_seconds": 70}', 'matching_information', '{"mcq_choice_id": "A"}', true, 1.000, 0.0000, 'reading', 273683, '2026-06-02 19:40:26.488954+00');
INSERT INTO exam_platform.attempt_responses VALUES ('e7e5554b-0fda-47ff-87c7-4abea5e0d9df', 'ee7d0677-ff5f-4975-a716-9142d4b76721', 0, '00000000-0000-4000-a000-000000000601', '{"id": "00000000-0000-4000-a000-000000000601", "type": "true_false_ng", "skill": "reading", "payload": {"prompt": "Beekeeping has been practised for over five millennia.", "options": [{"id": "A", "label": "True"}, {"id": "B", "label": "False"}, {"id": "C", "label": "Not Given"}], "passage": "The honeybee, Apis mellifera, has been kept by humans for at least 8,000 years. Beekeepers harvest honey, beeswax, propolis and royal jelly. While honey is consumed worldwide, beeswax has industrial applications ranging from cosmetics to electronics. Recent declines in bee populations have raised concerns among ecologists, although the precise causes remain debated.", "audio_url": null}, "cefr_level": "B1", "estimated_seconds": 70}', 'true_false_ng', '{"mcq_choice_id": "true"}', false, 0.000, 0.4130, 'reading', 42016, '2026-06-02 19:41:09.381662+00');
INSERT INTO exam_platform.attempt_responses VALUES ('e8fd281e-5200-43eb-b592-91b8ea1821d3', 'ee7d0677-ff5f-4975-a716-9142d4b76721', 0, '00000000-0000-4000-a000-000000000603', '{"id": "00000000-0000-4000-a000-000000000603", "type": "sentence_completion", "skill": "reading", "payload": {"prompt": "The shrinking of the Aral Sea began in the ____.", "options": [{"id": "A", "label": "1940s"}, {"id": "B", "label": "1960s"}, {"id": "C", "label": "1980s"}, {"id": "D", "label": "2000s"}], "passage": "The Aral Sea, once the world''s fourth-largest lake, has shrunk to a fraction of its former size since the 1960s. Soviet-era irrigation projects diverted the Amu Darya and Syr Darya rivers to grow cotton, leaving the sea starved of inflow. Today the lakebed is a salt-encrusted desert known as the Aralkum.", "audio_url": null}, "cefr_level": "B1", "estimated_seconds": 70}', 'sentence_completion', '{"text_answer": "1960s"}', false, 0.000, -0.0010, 'reading', 9135, '2026-06-02 19:41:19.272901+00');
INSERT INTO exam_platform.attempt_responses VALUES ('370ed9a2-4663-4ac0-b11d-5fdf391e4d28', 'ee7d0677-ff5f-4975-a716-9142d4b76721', 0, '1f39339a-818c-42a6-883f-18e0c70ed1ce', '{"id": "1f39339a-818c-42a6-883f-18e0c70ed1ce", "type": "mcq_single", "skill": "reading", "payload": {"prompt": "What is the main point the author makes about smartphones?", "options": [{"id": "A", "label": "They have completely replaced traditional forms of communication."}, {"id": "B", "label": "Their primary benefit is connecting people over long distances."}, {"id": "C", "label": "Their use requires a mindful approach to avoid negative social effects."}, {"id": "D", "label": "The main problem they cause is a constant state of distraction."}], "passage": "The proliferation of smartphones has fundamentally altered the landscape of social interaction. While these devices offer unprecedented connectivity, allowing individuals to communicate across vast distances, they also present challenges. Face-to-face conversations are sometimes replaced by digital messaging, which can lack the nuance of direct human contact. Moreover, the constant stream of notifications can lead to a state of perpetual distraction, making it difficult for people to be fully present in their immediate surroundings. It is crucial, therefore, for users to develop a conscious approach to their device usage, balancing the benefits of digital connection with the irreplaceable value of real-world engagement.", "audio_url": null}, "cefr_level": "B1", "estimated_seconds": 75}', 'mcq_single', '{"mcq_choice_id": "C"}', true, 1.000, -0.3053, 'reading', 8402, '2026-06-02 19:41:28.464295+00');
INSERT INTO exam_platform.attempt_responses VALUES ('8431ea24-0f6b-4048-a344-79240a2a5262', 'ee7d0677-ff5f-4975-a716-9142d4b76721', 0, '5b645df7-1998-444e-8c84-3bfd24d1a6cc', '{"id": "5b645df7-1998-444e-8c84-3bfd24d1a6cc", "type": "mcq_single", "skill": "reading", "payload": {"prompt": "What is the main idea of the passage regarding digital technology in the workplace?", "options": [{"id": "A", "label": "It has made remote work possible for the first time."}, {"id": "B", "label": "It has introduced both benefits and drawbacks for employees."}, {"id": "C", "label": "It causes more misunderstandings than traditional communication."}, {"id": "D", "label": "It is most useful for employees who work in different countries."}], "passage": "The rapid expansion of digital technology has fundamentally altered the landscape of the modern workplace. Tools like instant messaging and video conferencing allow for seamless collaboration between team members in different geographical locations, breaking down physical barriers to communication. This has enabled the rise of remote work, offering employees greater flexibility. However, this constant connectivity can also be a disadvantage. The line between professional and personal time often becomes blurred, with employees feeling pressure to be available outside of traditional working hours. Furthermore, an over-reliance on digital communication can sometimes lead to misunderstandings that would be less likely to occur in face-to-face interactions.", "audio_url": null}, "cefr_level": "B1", "estimated_seconds": 75}', 'mcq_single', '{"mcq_choice_id": "B"}', true, 1.000, -0.1330, 'reading', 7858, '2026-06-02 19:41:37.202408+00');
INSERT INTO exam_platform.attempt_responses VALUES ('5e2683f8-4f47-4d62-a644-51bf42cffe9d', '8214f4e2-2693-434e-8c1c-806051fac45e', 0, '00000000-0000-4000-a000-000000000201', '{"id": "00000000-0000-4000-a000-000000000201", "type": "mcq_single", "skill": "listening", "payload": {"prompt": "How much does the library card cost per year?", "options": [{"id": "A", "label": "2,000 so''m"}, {"id": "B", "label": "5,000 so''m"}, {"id": "C", "label": "10,000 so''m"}, {"id": "D", "label": "Free"}], "passage": null, "audio_url": "/audio/listening/library_dialog.m4a", "transcript": "The annual library card is five thousand so''m and gives you access to every branch for twelve months."}, "cefr_level": "B1", "estimated_seconds": 120}', 'mcq_single', '{"mcq_choice_id": "A"}', false, 0.000, 0.0000, 'listening', 41385, '2026-06-02 19:53:03.340502+00');
